import{_ as e,o as a,c as t,ag as o}from"./chunks/framework.DzGOF12C.js";const p=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"사단칠정 논쟁 (이황 ↔ 기대승)","slug":"사단칠정-논쟁-이황-↔-기대승","link":"#사단칠정-논쟁-이황-↔-기대승","children":[{"level":3,"title":"퇴계의 수정","slug":"퇴계의-수정","link":"#퇴계의-수정","children":[]},{"level":3,"title":"고봉의 반박","slug":"고봉의-반박","link":"#고봉의-반박","children":[]},{"level":3,"title":"퇴계의 재반박","slug":"퇴계의-재반박","link":"#퇴계의-재반박","children":[]},{"level":3,"title":"고봉의 재반박","slug":"고봉의-재반박","link":"#고봉의-재반박","children":[]},{"level":3,"title":"퇴계의 재반박","slug":"퇴계의-재반박-1","link":"#퇴계의-재반박-1","children":[]},{"level":3,"title":"고봉의 재재반박","slug":"고봉의-재재반박","link":"#고봉의-재재반박","children":[]},{"level":3,"title":"이후 전개","slug":"이후-전개","link":"#이후-전개","children":[]}]}],"relativePath":"philosophy/Korean-Philosophy/04. 사단칠정 논쟁.md","filePath":"philosophy/Korean-Philosophy/04. 사단칠정 논쟁.md"}'),r={name:"philosophy/Korean-Philosophy/04. 사단칠정 논쟁.md"};function i(n,l,s,h,d,c){return a(),t("div",null,[...l[0]||(l[0]=[o('<h2 id="사단칠정-논쟁-이황-↔-기대승" tabindex="-1">사단칠정 논쟁 (이황 ↔ 기대승) <a class="header-anchor" href="#사단칠정-논쟁-이황-↔-기대승" aria-label="Permalink to &quot;사단칠정 논쟁 (이황 ↔ 기대승)&quot;">​</a></h2><p><strong>기대승의 문제 제기</strong>: 이황이 사단(四端)과 칠정(七情), 리(理)와 기(氣)를 너무 분리시켜 두었다는 비판.</p><p><strong>이황(퇴계)의 원래 입장</strong>: 사단은 리에서 발현되어 나온 것이고, 칠정은 기에서 발현되어 나온 것이다(<strong>사단발어리 칠정발어기</strong>). 사단도 감정, 칠정도 감정이지만 — 사단은 순수하게 선한 감정, 칠정은 악이 되기 쉬운 감정이라는 점에서, 사단과 칠정은 선악의 측면에서 서로 다른 감정이므로 구분해야 함.</p><h3 id="퇴계의-수정" tabindex="-1">퇴계의 수정 <a class="header-anchor" href="#퇴계의-수정" aria-label="Permalink to &quot;퇴계의 수정&quot;">​</a></h3><ul><li><strong>사단</strong>: 순수한 리 → 선하지 않음이 없음</li><li><strong>칠정</strong>: 기를 겸함 → 선·악이 혼재</li></ul><h3 id="고봉의-반박" tabindex="-1">고봉의 반박 <a class="header-anchor" href="#고봉의-반박" aria-label="Permalink to &quot;고봉의 반박&quot;">​</a></h3><p>사단과 칠정은 모두 같은 감정이다. 둘 다 같은 감정이라면, 결국 기(심)가 리(성)를 드러낸 것 — 즉 리와 기가 결합한 결과물 아닌가? <strong>사단은 칠정 가운데 선한 것만을 가리킨 것</strong>일 뿐이다.</p><h3 id="퇴계의-재반박" tabindex="-1">퇴계의 재반박 <a class="header-anchor" href="#퇴계의-재반박" aria-label="Permalink to &quot;퇴계의 재반박&quot;">​</a></h3><ol><li>같은 것이라면 왜 이름이 다른가? — 말하고자 하는 측면에서 볼 때 서로 다른 것이다.</li><li>리와 기는 <strong>생성론적 측면</strong>(존재물을 발생시키는 관점)에서는 분리시킬 수 없는 것이 맞음. 리가 기질에 들어오면 &#39;성&#39;이라 하며 이를 <strong>기질지성</strong>, 리가 기질에 들어오지 않은 상태를 <strong>본연지성</strong>이라 함 (우주의 보편적 법칙 상태로 있는 성 = 본연지성, 그것이 기질에 들어온 것 = 기질지성 — <strong>리일분수</strong>의 개념). 성도 생성론적 측면에서는 분리해서 볼 수 없지만, <strong>가치론적 측면</strong>에서는 기질지성과 본연지성으로 구분하는 것이 가능함.</li><li>주자도 이미 사단은 리가 발현한 것, 칠정은 기가 발현한 것이라고 말한 바 있다.</li></ol><h3 id="고봉의-재반박" tabindex="-1">고봉의 재반박 <a class="header-anchor" href="#고봉의-재반박" aria-label="Permalink to &quot;고봉의 재반박&quot;">​</a></h3><ol><li>감정은 (본성인 리를 기가 발현시킨) 기질지성이 발현한 것으로, 하나의 종류일 뿐이다 — 감정은 리와 기 모두를 겸하므로 선·악을 모두 포함한다.</li><li>사단은 칠정 가운데 선한 감정(중절한 칠정)만을 가리킨 것일 뿐이다 (발현된 칠정 중 절도에 맞는 것과 맞지 않는 것을 나누는 관점).</li><li>주자가 그렇게 말했다는 것은 단 한 번 기록된 것으로, 특수한 맥락에서 나온 말일 뿐이다.</li></ol><h3 id="퇴계의-재반박-1" tabindex="-1">퇴계의 재반박 <a class="header-anchor" href="#퇴계의-재반박-1" aria-label="Permalink to &quot;퇴계의 재반박&quot;">​</a></h3><p>당신은 사단과 칠정이 같다는 관점에서만 말하고 있다. 나는 사단과 칠정이 다르다는 관점에서 말하고 있다 — 당신이 근거로 든 주자의 &#39;악기(樂記)&#39; 관련 설명은 모두 (사단과 칠정을) 섞어서 보는 관점에서 나온 말일 뿐이다. 이를 근거로 (사단과 칠정을) 구분해서 보는 관점을 공격한다면, 애초에 서로 다른 전제 위에 있으므로 대응할 말이 없다.</p><p><strong>결론(잠정)</strong>: 사단은 리가 발함에 기가 따른 것이고(理發而氣隨之), 칠정은 기가 발함에 리가 탄 것이다(氣發而理乘之).</p><h3 id="고봉의-재재반박" tabindex="-1">고봉의 재재반박 <a class="header-anchor" href="#고봉의-재재반박" aria-label="Permalink to &quot;고봉의 재재반박&quot;">​</a></h3><ol start="2"><li>사단도 절도에 맞지 않는 경우가 있을 수 있다 — (다만 이 지점은 논란의 여지가 있음: 사단이 원리상 부중절할 수 있는가 하는 문제가 남음. 현실적 측면에서는 그런 사례가 있을 수 있다는 정도로 받아들여짐)</li></ol><h3 id="이후-전개" tabindex="-1">이후 전개 <a class="header-anchor" href="#이후-전개" aria-label="Permalink to &quot;이후 전개&quot;">​</a></h3><p>논쟁이 같은 논점을 반복하는 방향으로 흐르자, 퇴계가 세 편의 편지(3서)를 작성했으나 보내지 않고 대신 시를 지어 보냄.</p>',18)])])}const u=e(r,[["render",i]]);export{p as __pageData,u as default};
